import config from '../lib/config';

const {OPENAI_API_KEY} = config;

// Create a wrapper/adapter client.
interface ClientAdapter {
  createChatCompletion(params: {
    model: string;
    temperature: number;
    messages: Array<{ role: string; content: string }>;
  }): Promise<{
    data?: {
      choices: Array<{
        message?: {
          content?: string | null;
        };
      }>;
    };
  }>;
}

let client: ClientAdapter;

const isMock = typeof (OpenAIModule as any).OpenAIApi === 'function';

if (isMock) {
  // Use the mocked structure
  const Configuration = (OpenAIModule as any).Configuration;
  const OpenAIApi = (OpenAIModule as any).OpenAIApi;
