import config from '../lib/config';

const {OPENAI_API_KEY} = config;

interface ChatMessage {
  role: string;
  content: string;
}

interface ChatCompletionParams {
  model: string;
  temperature: number;
  messages: ChatMessage[];
}

interface ChatCompletionResponse {
  data?: {
    choices: Array<{
      message?: {
        content?: string | null;
      };
    }>;
  };
}

interface ClientAdapter {
  createChatCompletion(params: ChatCompletionParams): Promise<ChatCompletionResponse>;
}

let client: ClientAdapter;

const isMock = typeof (OpenAIModule as any).OpenAIApi === 'function';

if (isMock) {
  const Configuration = (OpenAIModule as any).Configuration;
